-- Retire the Bog Witch scorings. GET /api/scoring filters on is_active, so
-- this drops them from the trophy calculator and every other scoring picker.
-- GET /api/scoring/{code} ignores the flag, so historical Bog Witch events
-- still resolve their own scoring and render correctly.
UPDATE scorings SET is_active = false WHERE code LIKE '%-bog';
